PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;
 CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'seller', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS catalog(id TEXT PRIMARY KEY, make TEXT NOT NULL, model TEXT NOT NULL, generation TEXT NOT NULL, year_from INTEGER NOT NULL, year_to INTEGER NOT NULL, facelift TEXT NOT NULL, variant TEXT NOT NULL, market TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY, catalog_id TEXT NOT NULL REFERENCES catalog(id), version INTEGER NOT NULL, filename TEXT NOT NULL, size INTEGER NOT NULL, source_url TEXT NOT NULL, creator TEXT NOT NULL, license TEXT NOT NULL, attribution TEXT NOT NULL, limitations TEXT NOT NULL, config TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(catalog_id,version));
 CREATE TABLE IF NOT EXISTS listings(id TEXT PRIMARY KEY, seller_id TEXT NOT NULL REFERENCES users(id), catalog_id TEXT NOT NULL REFERENCES catalog(id), asset_id TEXT REFERENCES assets(id), title TEXT NOT NULL, year INTEGER NOT NULL, price INTEGER NOT NULL, mileage INTEGER NOT NULL, city TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', demo INTEGER NOT NULL DEFAULT 0, unavailable TEXT NOT NULL DEFAULT '[]', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, original TEXT NOT NULL, display TEXT NOT NULL, thumbnail TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS photo_areas(photo_id TEXT NOT NULL REFERENCES photos(id) ON DELETE CASCADE, area_id TEXT NOT NULL, PRIMARY KEY(photo_id,area_id));
 CREATE TABLE IF NOT EXISTS markers(id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id), label TEXT NOT NULL, damage INTEGER NOT NULL DEFAULT 0, position TEXT NOT NULL);
 CREATE INDEX IF NOT EXISTS listing_status ON listings(status,created_at);
 CREATE INDEX IF NOT EXISTS photo_listing ON photos(listing_id,sort_order);
 INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
